import time
from confluent_kafka import Producer
from confluent_kafka.admin import AdminClient,ConfigResource,ResourceType

def recover_isr(c,name,inventory):
    if inventory.get('approved') is not True:raise ValueError('approval required')
    ids=inventory.get('stopped_brokers',[])
    if len(ids)!=2 or set(ids)!=c.stopped or any(c.nodes[i]['role']!='broker' for i in ids):raise ValueError('exact owned data-replica inventory required')
    resource=ConfigResource(ResourceType.TOPIC,name)
    admin=AdminClient(c.config())
    minimum=int(admin.describe_configs([resource])[resource].result(6)['min.insync.replicas'].value)
    before=c.partition(name)
    if minimum!=2 or len(before.replicas)!=3 or len(before.isrs)!=1:raise ValueError('unexpected replication contract')
    identity=c.identity()
    c.resume_nodes(ids)
    after=c.partition(name,3)
    if c.identity()!=identity:raise ValueError('storage/config identity changed')
    delivered=[]
    p=Producer(dict(c.config(),**{'acks':'all','enable.idempotence':True,'message.timeout.ms':10000}))
    p.produce(name,inventory['confirmation'],partition=0,on_delivery=lambda err,msg:delivered.append(err.code() if err else 0))
    p.flush(12)
    if delivered!=[0]:raise ValueError('no native durable acknowledgement '+repr(delivered))
    return {'isr':sorted(after.isrs),'replicas':sorted(after.replicas),'minimum':minimum,'delivered':True}

