    if formatted.returncode:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: format '+formatted.stdout+formatted.stderr)
    self.nodes[node_id]={'role':role,'node':node,'config':config,'env':env}
  for node_id,node in self.nodes.items():
   log=(node['node']/'process.log').open('w+');self.handles.append(log)
   node['process']=subprocess.Popen(['/opt/kafka/bin/kafka-server-start.sh',str(node['config'])],env=node['env'],stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
  deadline=time.monotonic()+40
  while time.monotonic()<deadline:
   if any(n['process'].poll() is not None for n in self.nodes.values()):break
   try:
