 def admin(self):
  key=self.config()['bootstrap.servers']
  if key not in self.admin_clients:self.admin_clients[key]=AdminClient(self.config())
  return self.admin_clients[key]
 def pause_nodes(self,node_ids):
  for node_id in node_ids:
   os.killpg(self.nodes[node_id]['process'].pid,signal.SIGSTOP);self.stopped.add(node_id)
 def resume_nodes(self,node_ids):
  for node_id in node_ids:
   if node_id not in self.nodes:raise ValueError('unknown owned node')
   os.killpg(self.nodes[node_id]['process'].pid,signal.SIGCONT);self.stopped.discard(node_id)
