    actual=s.inventory()
    for key in ['application_id','store','schema','java_sha256','changelog','changelog_topic_id','input_committed']:
        if actual[key]!=manifest[key]:raise ValueError('recovery inventory mismatch '+key)
    if 'compact' not in actual['cleanup_policy'] or actual['changelog_high']<=actual['changelog_low'] or actual['input_committed']<0:raise ValueError('no trustworthy recovery log/point')
    if s.proc is not None and s.proc.poll() is None:raise ValueError('recovery requires stopped owner')
    s.launch()
    deadline=time.monotonic()+20
    try:
        while time.monotonic()<deadline:
            snapshot=s.snapshot()
            if snapshot and snapshot['state']=='RUNNING' and snapshot['restored']>0:
                business={key:snapshot[key] for key in ['alpha','beta']}
                if business!=manifest['business_state']:raise ValueError('recovered business point differs from authority')
                proof={'application_id':s.application_id,'changelog_topic_id':actual['changelog_topic_id'],'input_committed':actual['input_committed'],'business_state':business,'restored_records':snapshot['restored'],'business_ready':True}
